import numpy as np

def saisie_taille():
    arret=False
    while not arret:
        try:
            n=int(input("Entrer la taille de T(5-10):"))
            arret=5<=n<=10
        except:
            arret=False
            
    return n
def remplir(t,n):
    ## remplissage manuel
    for i in range(n):
        arret=False
        while arret==False:
            try:
                t[i]=int(input("Entrer T["+str(i)+"]="))
                arret=True
            except:
                arret=False
                
def tri_fusion(t,d,f):
    if d<f:
        milieu=(d+f)//2
        tri_fusion(t,d,milieu)
        tri_fusion(t,milieu+1,f)
        fusion(t,d,milieu,t,milieu+1,f,t)
def fusion(t1,d1,f1,t2,d2,f2,t):
    # copie de T dans un tableau temporaire
    tmp=np.array([int]*n)
    for i in range(n):
        tmp[i]=t[i]
    # initilialisations
    k=d1;i=d1;j=d2
    # aucun des tableau n'est terminé
    while i<=f1 and j<=f2:
        if t1[i]<=t2[j]:
            tmp[k]=t1[i]
            i=i+1
        else:
            tmp[k]=t2[j]
            j=j+1
        k=k+1
    ### T1 ou T2 est terminé
    # T2 est terminé 
    while i<=f1:
        tmp[k]=t1[i]
        i=i+1
        k=k+1
    # T1 est terminé
    while j<=f2:
        tmp[k]=t2[j]
        j=j+1
        k=k+1
    ### recopie de temp dans t
    for i in range(n):
        t[i]=tmp[i]
def afficher(t,n):
    for i in range(n):
        print(t[i]," | ",end="")
    print()
############# PP #############
n=saisie_taille()
t=np.array([int]*n)
remplir(t,n)
print("------ Avant Tri ------")
afficher(t,n)
tri_fusion(t,0,n-1)
print("------ apres Tri ------")
afficher(t,n)
